import React, { useRef } from 'react';
import type { Field } from '@cloud-materials/common/formily/core';
import { onFormValuesChange } from '@cloud-materials/common/formily/core';
import { CTableEditor, CForm, Button } from '@cloud-materials/common';

const dataGen = (pageSize = 10, currentPage = 1): Promise<any> => {
  return new Promise(resolve => {
    window.setTimeout(() => {
      resolve({
        data: Array.from({ length: pageSize }, (_, index) => {
          const idx = (currentPage - 1) * pageSize + index;
          return {
            name: 'name' + idx,
            age: 18,
            checkbox1: idx % 2 === 0 ? true : false,
            checkbox2: idx % 2 === 1 ? true : false,
            notEditable: '不可编辑 ' + idx,
          };
        }),
        total: 50,
      });
    }, 1000);
  });
};

export default () => {
  const tableEditorRef = useRef<any>(null);
  const config = CTableEditor.defineConfig({
    // 在 tableConfig 中编写 CTable 配置
    tableConfig: {
      // 如果想要批量删除，需配置 rowSelection
      rowSelection: {
        type: 'checkbox',
      },
      columns: [
        {
          title: '名字',
          dataIndex: 'name',
          width: 200,
          // 相比 CTable 的 column 配置，CTableEditor 中在 column 中加了一个 editConfig 配置
          // editConfig 中的 fieldConfig 就是 CForm 的 Field 配置
          // editConfig 也支持配置为函数，函数参数 options 对象中包含:
          // table、tableEditor、column、row、cell 领域模型，以及 rowData, cellData
          editConfig: ({ cellData }) => {
            return {
              // editable 默认为 true，只要你配置了 fieldConfig 就认为是可编辑组件
              // 如果想根据数据配置某些单元格不可编辑，需要手动配置 editable = false
              editable: cellData !== 'name2',
              fieldConfig: {
                componentOptions: CForm.defineComponentOption('Input'),
                decoratorOptions: CForm.defineDecoratorOptions('FormItem', {
                  helpLayout: 'popover',
                }),
                required: true,
              },
            };
          },
        },
        {
          title: '年龄',
          dataIndex: 'age',
          width: 200,
          editConfig: {
            fieldConfig: {
              componentOptions: CForm.defineComponentOption('InputNumber'),
              decoratorOptions: CForm.defineDecoratorOptions('FormItem', {
                helpLayout: 'popover',
              }),
              required: true,
            },
          },
        },
        {
          title: 'Checkbox 1',
          dataIndex: 'checkbox1',
          width: 200,
          editConfig: {
            fieldConfig: {
              componentOptions: CForm.defineComponentOption('Checkbox', (_form, parentField) => {
                // 从 parentField 的 value 中取兄弟节点的值要加上可选链(即 ?.), 因为加载过程中 value 可能为 undefined
                const checkbox2 = (parentField as unknown as Field)?.value?.checkbox2;
                return {
                  disabled: !!checkbox2,
                };
              }),
            },
          },
        },
        {
          title: 'Checkbox 2',
          dataIndex: 'checkbox2',
          width: 200,
          editConfig: {
            fieldConfig: {
              componentOptions: CForm.defineComponentOption('Checkbox', (_form, parentField) => {
                // 从 parentField 的 value 中取兄弟节点的值要加上可选链(即 ?.), 因为加载过程中 value 可能为 undefined
                const checkbox1 = (parentField as unknown as Field)?.value?.checkbox1;
                return {
                  disabled: !!checkbox1,
                };
              }),
            },
          },
        },
        {
          title: '不可编辑字段',
          dataIndex: 'notEditable',
          width: 100,
        },
      ],
      fetcher({ pageSize, currentPage }) {
        return dataGen(pageSize, currentPage);
      },
    },
    // 在 tableConfig 中编写 formily 配置，支持配置为函数
    // 注意: 受控模式下请谨慎配置为函数，可能 tableEditor 内部的 form, table 实例还没有完成初始化
    formConfig: tableEditor => {
      return {
        effects: () => {
          // 使用 TableEditor 提供的 helper，打印指定 index 的行的数据
          onFormValuesChange(() => {
            // 当 tableEditor 内部的 form, table 实例完成初始化后再进行操作
            if (tableEditor.table && tableEditor.form) {
              console.log('第 3 行数据:', CTableEditor.helper.getRowDataByIndex({ index: 3, tableEditor }));
            }
          });
        },
      };
    },
    // 在表格下方渲染自定义的内容，支持响应式
    renderAfter: () => {
      return (
        /**
         * CTableEditor 的静态属性中包含了若干按钮，
         * 包括新增行按钮、删除行按钮、提交按钮、撤销按钮以及切换编辑态按钮，
         * 这些按钮封装了基本的逻辑，可以开箱即用，同时它们的 props 均支持响应式，拓展性强
         */
        <div>
          <CTableEditor.AddRow
            // 编写新增行函数, tableEditor 实例作为函数参数
            addRow={tableEditor => ({
              name: `default_name_${tableEditor.currentData.length}`,
              age: 18,
              checkbox1: true,
              checkbox2: false,
              notEditable: 'default_notEditable',
            })}
            // 新增行后的回调
            onAdd={(rowData, tableEditor) => {
              console.log('新增的行', rowData);
              console.log('当前数据', tableEditor.currentData);
            }}
          />
          <CTableEditor.AddRow
            // 新增的数据是放在顶部还是底部，可选 top | bottom，默认在底部新增
            position="top"
            text="在顶部新增一行"
            // 编写新增行函数, tableEditor 实例作为函数参数
            addRow={tableEditor => ({
              name: `default_name_${tableEditor.currentData.length}`,
              age: 18,
              checkbox1: true,
              checkbox2: false,
              notEditable: 'default_notEditable',
            })}
            // 新增行后的回调
            onAdd={(rowData, tableEditor) => {
              console.log('新增的行', rowData);
              console.log('当前数据', tableEditor.currentData);
            }}
          />
          <CTableEditor.DeleteRow
            // 删除行后的回调
            onDelete={(rowData, tableEditor) => {
              console.log('被删除的行', rowData);
              console.log('当前数据', tableEditor.currentData);
            }}
          />
          <CTableEditor.Submit
            onSubmit={(value, tableEditor) => {
              console.log(`获取当前 TableEditor 的数据: ${JSON.stringify(value)}`);
              console.log(`获取新增的行: ${JSON.stringify(tableEditor.addedRows)}`);
              console.log(`获取删除的行: ${JSON.stringify(tableEditor.deletedRows)}`);
              console.log(`获取变更的行: ${JSON.stringify(tableEditor.updatedRows)}`);
              // 如果想保存修改后的状态，即清空操作历史、将当前状态作为新的初始值，需要手动调用 tableEditor.save()
              tableEditor.save();
            }}
          />
          <CTableEditor.Undo text="撤销上一步" />
          <CTableEditor.Undo type="AllSteps" text="撤销全部" />
          <CTableEditor.Switch
            // 切换编辑态后的回调
            onSwitch={editable => {
              console.log('切换编辑态, 当前编辑态:', editable);
            }}
            // 配置 content 可以完全自定义按钮，也支持响应式
            content={tableEditor => {
              if (tableEditor.editable) {
                return <Button type="primary">切换编辑态-当前状态-编辑态</Button>;
              } else {
                return <Button>切换编辑态-当前状态-只读态</Button>;
              }
            }}
          />
        </div>
      );
    },
  });

  return <CTableEditor config={config} ref={tableEditorRef} />;
};

import React, { useRef } from 'react';
import { CTableEditor, CForm, Button, Message } from '@cloud-materials/common';
