        {
          title: '性别',
          dataIndex: 'gender',
          width: 200,
          editConfig: {
            fieldConfig: {
              componentOptions: CForm.defineComponentOption('Select'),
              decoratorOptions: CForm.defineDecoratorOptions('FormItem', {
                helpLayout: 'popover',
              }),
              dataSource: [
                { label: '男', value: 'man' },
                { label: '女', value: 'woman' },
              ],
              required: true,
            },
          },
        },
        {
          title: '年龄',
          dataIndex: 'age',
          width: 200,
          editConfig: {
            fieldConfig: {
              componentOptions: CForm.defineComponentOption('InputNumber'),
              // 在组件右侧显示 tips
              decoratorOptions: CForm.defineDecoratorOptions('FormItem', {
                controlPopover: {
                  helperTips: ['整数', '范围为1-100'],
                  trigger: 'hover',
                  position: 'right',
                },
              }),
              rules: [
                { required: true },
                {
                  validator: async ({ value, callback }) => {
                    if (value % 1 !== 0) {
                      callback('整数');
                    } else if (value < 1 || value > 100) {
                      callback('范围为1-100');
                    } else {
                      callback('');
                    }
                  },
                },
              ],
            },
          },
        },
        {
          title: 'Checkbox 1',
          dataIndex: 'checkbox1',
          width: 100,
          editConfig: {
            fieldConfig: {
              componentOptions: CForm.defineComponentOption('Checkbox', (_form, parentField) => {
                // 从 parentField 的 value 中取兄弟节点的值要加上可选链(即 ?.), 因为加载过程中 value 可能为 undefined
                const checkbox2 = (parentField as unknown as Field)?.value?.checkbox2;
                return {
                  disabled: !!checkbox2,
                };
              }),
              decoratorOptions: CForm.defineDecoratorOptions('FormItem'),
            },
          },
        },
        {
          title: 'Checkbox 2',
          dataIndex: 'checkbox2',
          width: 100,
          editConfig: {
            fieldConfig: {
              componentOptions: CForm.defineComponentOption('Checkbox', (_form, parentField) => {
                // 从 parentField 的 value 中取兄弟节点的值要加上可选链(即 ?.), 因为加载过程中 value 可能为 undefined
                const checkbox1 = (parentField as unknown as Field)?.value?.checkbox1;
                return {
                  disabled: !!checkbox1,
                };
              }),
              decoratorOptions: CForm.defineDecoratorOptions('FormItem'),
            },
          },
        },
      ],
    },
    formConfig: {
      editable: true,
    },
    renderAfter: () => {
      return (
        <div>
          <CTableEditor.AddRow
            addRow={tableEditor => ({
              name: `default_name_${tableEditor.currentData.length}`,
              age: 18,
              checkbox1: true,
              checkbox2: false,
              number: `编号_${tableEditor.currentData.length}`,
            })}
            // 新增行后的回调
            onAdd={(rowData, tableEditor) => {
              console.log('新增的行', rowData);
              console.log('当前数据', tableEditor.currentData);
            }}
          />
          <CTableEditor.DeleteRow
            // 删除行后的回调
            onDelete={(rowData, tableEditor) => {
              console.log('被删除的行', rowData);
              console.log('当前数据', tableEditor.currentData);
            }}
          />
          <CTableEditor.Undo type="AllSteps" text="撤销全部" />
          <CTableEditor.Switch />
        </div>
      );
    },
  });

  // 外部 Form 给 TableEditor 赋值
