    Message.info('TableEditor 数据将被设置为 3 项');
    const form = formRef.current;
    if (form) {
      form.setValuesIn('tableEditor', dataGen(3));
    }
  };

  const handleSubmit = () => {
    const form = formRef?.current;
    if (form) {
      form
        .submit((value: any) => {
          console.log(value);
        })
        .catch((err: any) => {
          console.log('submit error', err);
        });
    }
  };

  // 外部 Form reset 时，内部的 TableEditor 也会 reset
  const handleReset = () => {
    formRef?.current?.reset();
  };

  const formConfig = CForm.defineConfig({
    fields: [
      {
        name: 'tableEditor',
        title: '可编辑表格',
        decoratorOptions: CForm.defineDecoratorOptions('FormItem', {
          // 强制配置 TableEditor 不为 error 的校验状态
          // 原因是: 外部 Form 校验时，如果 TableEditor 中有一个字段校验不通过，那整个 TableEditor 都会被 FormItem 加上 'validateStatus-error' 的样式
          // 这会导致 TableEditor 内部所有 Input, Select 组件等都会加上报错状态
          // @ts-ignore
          validateStatus: 'no-status',
          // 重要!!!
          // TableEditor 作为受控组件使用时，如果要用 FormItem 包裹，需要传这个属性，否则性能会大幅下降
          hasInnerFormItem: true,
          // 因为 TableEditor 内部的字段已经会展示报错信息了，所以可以去掉 TableEditor 下方外部 Form 给予的报错
          help: [],
        }),
        componentOptions: {
          component: CTableEditor,
          props: { config },
        },
        // 设置组件初始值
        initialValue: dataGen(8),
      },
      {
        name: 'input',
        title: 'input',
        required: true,
        componentOptions: {
          component: 'Input',
        },
        decoratorOptions: CForm.defineDecoratorOptions('FormItem'),
      },
    ],
    effects: () => {
      onFormValuesChange(form => {
        console.log('onChange,value on Form', toJS(form.values), Date.now());
      });
    },
  });

  return (
    <div>
      <div style={{ display: 'flex', gap: 16, marginBottom: 16 }}>
        <Button onClick={() => console.log(toJS(formRef?.current?.values))}>打印 form values</Button>
        <Button onClick={setTableEditorValue}>设置 TableEditorValue</Button>
        <Button onClick={handleReset}>执行 form reset</Button>
      </div>
      <CForm ref={formRef} config={formConfig} />
      <Button type="primary" onClick={handleSubmit}>
        提交
      </Button>
    </div>
  );
};

