import React, { useRef } from 'react';
import { CTableEditor, CForm, Button, CModal } from '@cloud-materials/common';

const { EditableCell } = CTableEditor;

const dataGen = (pageSize = 10, currentPage = 1): Promise<any> => {
  return new Promise(resolve => {
    window.setTimeout(() => {
      resolve({
        data: Array.from({ length: pageSize }, (_, index) => {
