          dataIndex: 'name',
          width: 200,
          editConfig: {
            fieldConfig: {
              // 配置为 EditableCell
              componentOptions: CForm.defineComponentOption(EditableCell, {
                // EditableCell 组件接收 field props，配置 component 和 componentProps 来展示自定义组件
                // component 具有若干内置组件，包括 Input, InputNumber, Select, TextArea 等等，有类型提示
                field: {
                  component: 'Input',
                  componentProps: {
                    placeholder: '自定义 placeholder',
                  },
                },
              }),
              decoratorOptions: CForm.defineDecoratorOptions('FormItem'),
              required: true,
            },
          },
        },
        {
          title: '名字-点提交发送请求',
          dataIndex: 'name1',
          width: 200,
          editConfig: ({ table }) => ({
            fieldConfig: {
              // 配置为 EditableCell
              componentOptions: CForm.defineComponentOption(EditableCell, {
                // EditableCell 组件接收 field props，配置 component 和 componentProps 来展示自定义组件
                // component 具有若干内置组件，包括 Input, InputNumber, Select, TextArea 等等，有类型提示
                field: {
                  component: 'Input',
                  componentProps: {
                    placeholder: '自定义 placeholder',
                  },
                },
                // 当配置了 onSubmit 时，会在点击 确认 按钮时触发
                // 如果需要阻塞默认的提交行为（切换到非编辑态），则需要在 onSubmit 中返回 Promise.reject()
                onSubmit(value, oldValue) {
                  // onSubmit 中可以返回 Promise，该 Promise 的状态会决定编辑组件提交按钮的 loading 状态
                  // 防止点提交时将输入框切换到非编辑态
                  // CModal.open 的返回值是 CModal 中 onOk 的返回值，可以为 Promise
                  return CModal.open({
                    title: '是否提交',
                    content: (
                      <div>
                        <div>新值: {value}</div>
                        <div>旧值: {oldValue}</div>
                      </div>
                    ),
                    onOk: () => {
                      // 在 CModal 的 onOk 中返回 Promise 可以让「确定」按钮有 loading 效果
                      return new Promise(resolve => {
                        setTimeout(() => {
                          resolve(value);
                          // 在这里可以将单个单元格的修改通过发请求传给后端，成功后可以调用 table.refresh() 刷新表格
                          table.refresh();
                        }, 2000);
                      });
                      // 如果不返回 Promise 又希望不切换到非编辑态，需要返回 Promise.reject()
                      // return Promise.reject();
                    },
                  });
                },
              }),
              decoratorOptions: CForm.defineDecoratorOptions('FormItem'),
              required: true,
            },
          }),
        },
        {
          title: '名字-点提交阻塞默认行为',
          dataIndex: 'name2',
          width: 200,
          editConfig: {
            fieldConfig: {
              // 配置为 EditableCell
              componentOptions: CForm.defineComponentOption(EditableCell, {
                // EditableCell 组件接收 field props，配置 component 和 componentProps 来展示自定义组件
                // component 具有若干内置组件，包括 Input, InputNumber, Select, TextArea 等等，有类型提示
                field: {
                  component: 'Input',
                  componentProps: {
                    placeholder: '自定义 placeholder',
                  },
                },
                // 当配置了 onSubmit 时，会在点击 确认 按钮时触发
                // onSubmit 中可以返回 Promise，该 Promise 的状态会决定编辑组件提交按钮的 loading 状态
                // onSubmit 第三个参数为父组件下发的 onChange
                onSubmit(value, oldValue, onChange) {
                  // CModal.open 的返回值是 CModal 中 onOk 的返回值，可以为 Promise
                  return CModal.open({
                    title: '是否提交',
                    content: (
                      <div>
                        <div>新值: {value}</div>
                        <div>旧值: {oldValue}</div>
                      </div>
                    ),
                    onOk: () => {
                      // 如果需要在弹窗中点「确定」才能改变值，可以这样做
                      onChange(value);
                      return Promise.resolve();
                    },
                    onCancel: () => {
                      // 防止切换到非编辑态
                      return Promise.reject();
                    },
                  });
                },
              }),
              decoratorOptions: CForm.defineDecoratorOptions('FormItem'),
              required: true,
            },
          },
        },
        {
          title: '年龄',
          dataIndex: 'age',
          width: 200,
          editConfig: {
            fieldConfig: {
              componentOptions: CForm.defineComponentOption(EditableCell, {
                field: {
                  component: 'InputNumber',
                },
              }),
              decoratorOptions: CForm.defineDecoratorOptions('FormItem'),
              required: true,
              rules: [
                {
                  validator: async ({ value, callback }) => {
                    if (value === 2) {
                      callback('value 需要不等于2');
                    } else {
                      callback('');
                    }
                  },
                },
              ],
            },
          },
        },
        {
          title: '性别',
          dataIndex: 'gender',
          width: 200,
          editConfig: {
            fieldConfig: {
              componentOptions: CForm.defineComponentOption(EditableCell, {
                field: {
                  component: 'Select',
                  componentProps: {
                    options: [
                      { label: '男', value: 'man' },
                      { label: '女', value: 'woman' },
                    ],
                  },
                },
              }),
              decoratorOptions: CForm.defineDecoratorOptions('FormItem'),
              required: true,
            },
          },
        },
      ],
      fetcher({ pageSize, currentPage }) {
        return dataGen(pageSize, currentPage);
      },
    },
    renderBefore: tableEditor => {
      return (
        <div style={{ display: 'flex', gap: 16, marginBottom: 16 }}>
          <Button
            type="primary"
            onClick={() => {
              tableEditor.addRow({
                name: `default_name_${tableEditor.currentData.length}`,
                age: 18,
              });
            }}
          >
            增加行
          </Button>
          <Button
            status="danger"
            disabled={!tableEditor.table.selectedRowKeys.length}
            onClick={() => tableEditor.deleteRows()}
          >
            删除选中的行
          </Button>
          <Button disabled={!tableEditor.hasActionHistory} onClick={() => tableEditor.undo({ type: 'LastStep' })}>
            回退一步
          </Button>
          <Button disabled={!tableEditor.hasChanged} onClick={() => tableEditor.undo({ type: 'AllSteps' })}>
            撤回全部
          </Button>
        </div>
      );
    },
  });

  return <CTableEditor config={config} ref={tableEditorRef} />;
};

